export type RuntimeUiKey = keyof typeof messages
export const runtimeUiKeys = Object.freeze(Object.keys(messages) as RuntimeUiKey[])

/** Read-only catalogs expose parity for tests and exact-key callers, not a second locale store. */
export const runtimeUiCatalogs = Object.freeze(Object.fromEntries(runtimeUiLocales.map((locale, index) => [
  locale,
  Object.freeze(Object.fromEntries(runtimeUiKeys.map(english => [english, index === 0 ? english : messages[english][index - 1]])))
])) as Record<RuntimeUiLocale, Readonly<Record<RuntimeUiKey, string>>>)

/** Exact lookup only: no normalization, interpolation, parsing, or substring replacement. */
export function runtimeUiText(locale: string, english: string): string {
  if (!Object.hasOwn(runtimeUiCatalogs, locale)) {return english}
  const catalog = runtimeUiCatalogs[locale as RuntimeUiLocale]

  return Object.hasOwn(catalog, english) ? catalog[english as RuntimeUiKey] : english
}

export function useRuntimeUiText(): (english: string) => string {
  const { locale } = useI18n()

  return useCallback((english: string) => runtimeUiText(locale, english), [locale])
}

const templateKeys: ReadonlySet<string> = new Set(runtimeUiTemplateKeys)

/** Interpolate a finite authored template once; never parse or translate supplied values. */
export function runtimeUiFormat(locale: string, english: string, values: RuntimeUiValues): string {
  if (!templateKeys.has(english)) {return runtimeUiText(locale, english)}

  return runtimeUiText(locale, english).replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (placeholder, name: string) =>
    Object.hasOwn(values, name) ? String(values[name]) : placeholder
  )
}

export function useRuntimeUiFormat(): (english: string, values: RuntimeUiValues) => string {
  const { locale } = useI18n()

  return useCallback((english: string, values: RuntimeUiValues) => runtimeUiFormat(locale, english, values), [locale])
}
